-- ── hand-written: the two functions' search path ────────────────────────────────────────────────
-- Both run with the table owner's rights, so every name in them is written in full and their
-- search path is pg_catalog, then the session's temporary schema last. An empty search path is
-- not used: Postgres then looks for a type name in the session's temporary schema first, and a
-- session could make a temporary type called "uuid" whose check runs its own code as the owner
-- (found by this step's review, 2026-11-15; the functions of earlier steps are a joint fix).

-- ── hand-written: what a customer paid between two days ─────────────────────────────────────────
-- Whether a promise was kept: the money that came in from the customer from the day the promise
-- was made to the day promised, on receipts that stand (posted; a bounced or cancelled one does
-- not count). A cheque counts from the day it was received, as Step 32 counts it. The sales
-- manager does not read receipts, so this runs with the table owner's rights and first asks who
-- is reading; a member limited to some branches is told of those branches' receipts only.
CREATE FUNCTION app.customer_received(p_customer uuid, p_from date, p_to date) RETURNS numeric
  LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_tenant uuid := app.tenant_id();
  v_role public.member_role := app.tenant_role();
  v_scope uuid[] := app.tenant_branch_ids();
  v_sum numeric;
BEGIN
  IF v_tenant IS NULL OR v_role IS NULL OR v_role NOT IN ('owner', 'accountant', 'auditor', 'recovery_officer', 'sales_manager') THEN
    RAISE EXCEPTION 'not allowed to see what a customer has paid' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF p_customer IS NULL OR p_from IS NULL OR p_to IS NULL THEN
    RAISE EXCEPTION 'a customer and two days are needed' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  SELECT coalesce(sum(r.amount), 0) INTO v_sum
  FROM public.receipts r
  WHERE r.tenant_id = v_tenant AND r.customer_id = p_customer AND r.status = 'posted'
    AND r.receipt_date BETWEEN p_from AND p_to
    AND (v_scope IS NULL OR r.branch_id = ANY (v_scope));
  RETURN v_sum;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.customer_received(uuid, date, date) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.customer_received(uuid, date, date) TO app_runtime;
--> statement-breakpoint

-- ── hand-written: a customer's lines in the books, for the statement ────────────────────────────
-- The customer statement is read from the books, so it always agrees with them: every line that
-- names the customer in a receivables account (control type "ar") or in customer advances
-- ("customer_advances", where Step 32 keeps money received beyond the invoices). One row per
-- journal, its net effect on what the customer owes; a journal that only moves the customer's
-- money from one to the other (an advance set against invoices) changes nothing and is left
-- out. The first row is what the customer owed before the period, as debit or credit. The
-- recovery officer and the sales manager do not read journals, so this runs with the table
-- owner's rights and first asks who is reading. A member limited to some branches is shown
-- those branches' lines only: not another branch's, and not the opening balances, which belong
-- to the whole company, as in app.receivables_open.
CREATE FUNCTION app.customer_statement(p_customer uuid, p_from date, p_to date)
  RETURNS TABLE (line_date date, written_at timestamptz, source_type text, document_number text, debit numeric, credit numeric)
  LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_tenant uuid := app.tenant_id();
  v_role public.member_role := app.tenant_role();
  v_scope uuid[] := app.tenant_branch_ids();
  v_before numeric;
BEGIN
  IF v_tenant IS NULL OR v_role IS NULL OR v_role NOT IN ('owner', 'accountant', 'auditor', 'recovery_officer', 'sales_manager') THEN
    RAISE EXCEPTION 'not allowed to see a customer statement' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF p_customer IS NULL OR p_from IS NULL OR p_to IS NULL OR p_from > p_to THEN
    RAISE EXCEPTION 'a customer and a period are needed' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  SELECT coalesce(sum(l.debit - l.credit), 0) INTO v_before
  FROM public.journal_lines l
  JOIN public.journals j ON j.tenant_id = l.tenant_id AND j.id = l.journal_id
  JOIN public.accounts a ON a.tenant_id = l.tenant_id AND a.id = l.account_id
  WHERE l.tenant_id = v_tenant AND l.customer_id = p_customer AND a.control_type IN ('ar', 'customer_advances') AND j.journal_date < p_from
    AND (v_scope IS NULL OR l.branch_id = ANY (v_scope));
  RETURN QUERY SELECT p_from, '-infinity'::timestamptz, 'opening'::text, NULL::text, greatest(v_before, 0), greatest(-v_before, 0);
  RETURN QUERY
    SELECT j.journal_date, j.created_at, j.source_type, j.document_number,
      greatest(sum(l.debit - l.credit), 0), greatest(sum(l.credit - l.debit), 0)
    FROM public.journal_lines l
    JOIN public.journals j ON j.tenant_id = l.tenant_id AND j.id = l.journal_id
    JOIN public.accounts a ON a.tenant_id = l.tenant_id AND a.id = l.account_id
    WHERE l.tenant_id = v_tenant AND l.customer_id = p_customer AND a.control_type IN ('ar', 'customer_advances')
      AND j.journal_date BETWEEN p_from AND p_to
      AND (v_scope IS NULL OR l.branch_id = ANY (v_scope))
    GROUP BY j.id, j.journal_date, j.created_at, j.source_type, j.document_number
    HAVING sum(l.debit - l.credit) <> 0
    ORDER BY j.journal_date, j.created_at, j.id;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.customer_statement(uuid, date, date) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.customer_statement(uuid, date, date) TO app_runtime;
